// Generated by `npx @polishd/next init`, then edited for the demo.
import { initPolishd } from "@polishd/next/client";

// The demo bar can show Queuebird with every fix applied. That preview isn't
// the site Polishd is measuring, so nothing captured while it's on is sent:
// the dashboard keeps describing the site as it was generated. A real app
// doesn't need any of this — it's `initPolishd()` and nothing else.
// (`NEXT_PUBLIC_DEMO_CAPTURE_FIXED=on` sends it anyway: that's how the fixes
// are checked, by scanning the fixed site into a throwaway store.)
const KEEP = process.env.NEXT_PUBLIC_DEMO_CAPTURE_FIXED === "on";
const polished = () => !KEEP && !!document.documentElement.dataset.fix;
const isIngest = (url: unknown) => String(url).includes("/api/polishd");

const beacon = navigator.sendBeacon?.bind(navigator);
if (beacon) {
  navigator.sendBeacon = (url, data) => (polished() && isIngest(url) ? true : beacon(url, data));
}

const send = window.fetch.bind(window);
window.fetch = (input, init) =>
  polished() && isIngest(input instanceof Request ? input.url : input)
    ? Promise.resolve(new Response('{"ok":true,"stored":0}', { headers: { "content-type": "application/json" } }))
    : send(input, init);

initPolishd();
